import{_ as t,o,c as r,l as s,t as n,N as a}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"chmod | x-cmd man (man1) | change file mode bits","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | chmod - change file mode bits","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"chmod | x-cmd man (man1) | change file mode bits"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | chmod - change file mode bits"}]]},"headers":[],"params":{"isMan":true,"man":"chmod","category":"man1","desc":"change file mode bits"},"relativePath":"man1/chmod.md","filePath":"man1/chmod.md"}'),i={name:"man1/chmod.md"},d={class:"visually-hidden"},h=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>chmod - change file mode bits</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>chmod</strong> [<em>OPTION</em>]... <em>MODE</em>[<em>,MODE</em>]... <em>FILE</em>... <br> <strong>chmod</strong> [<em>OPTION</em>]... <em>OCTAL-MODE FILE</em>... <br> <strong>chmod</strong> [<em>OPTION</em>]... <em>--reference=RFILE FILE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This manual page documents the GNU version of <strong>chmod</strong>. <strong>chmod</strong> changes the file mode bits of each given file according to <em>mode</em>, which can be either a symbolic representation of changes to make, or an octal number representing the bit pattern for the new mode bits.</p><p>The format of a symbolic mode is [ <strong>ugoa</strong>. . .][[<strong>-+=</strong>][<em>perms</em>. . .]. . .], where <em>perms</em> is either zero or more letters from the set <strong>rwxXst</strong>, or a single letter from the set <strong>ugo</strong>. Multiple symbolic modes can be given, separated by commas.</p><p>A combination of the letters <strong>ugoa</strong> controls which users&#39; access to the file will be changed: the user who owns it (<strong>u</strong>), other users in the file&#39;s group (<strong>g</strong>), other users not in the file&#39;s group (<strong>o</strong>), or all users (<strong>a</strong>). If none of these are given, the effect is as if (<strong>a</strong>) were given, but bits that are set in the umask are not affected.</p><p>The operator <strong>+</strong> causes the selected file mode bits to be added to the existing file mode bits of each file; <strong>-</strong> causes them to be removed; and <strong>=</strong> causes them to be added and causes unmentioned bits to be removed except that a directory&#39;s unmentioned set user and group ID bits are not affected.</p><p>The letters <strong>rwxXst</strong> select file mode bits for the affected users: read (<strong>r</strong>), write (<strong>w</strong>), execute (or search for directories) (<strong>x</strong>), execute/search only if the file is a directory or already has execute permission for some user (<strong>X</strong>), set user or group ID on execution (<strong>s</strong>), restricted deletion flag or sticky bit (<strong>t</strong>). Instead of one or more of these letters, you can specify exactly one of the letters <strong>ugo</strong>: the permissions granted to the user who owns the file (<strong>u</strong>), the permissions granted to other users who are members of the file&#39;s group (<strong>g</strong>), and the permissions granted to users that are in neither of the two preceding categories (<strong>o</strong>).</p><p>A numeric mode is from one to four octal digits (0-7), derived by adding up the bits with values 4, 2, and 1. Omitted digits are assumed to be leading zeros. The first digit selects the set user ID (4) and set group ID (2) and restricted deletion or sticky (1) attributes. The second digit selects permissions for the user who owns the file: read (4), write (2), and execute (1); the third selects permissions for other users in the file&#39;s group, with the same values; and the fourth for other users not in the file&#39;s group, with the same values.</p><p><strong>chmod</strong> never changes the permissions of symbolic links; the <strong>chmod</strong> system call cannot change their permissions. This is not a problem since the permissions of symbolic links are never used. However, for each symbolic link listed on the command line, <strong>chmod</strong> changes the permissions of the pointed-to file. In contrast, <strong>chmod</strong> ignores symbolic links encountered during recursive directory traversals.</p><h2 id="setuid-and-setgid-bits" tabindex="-1">SETUID AND SETGID BITS <a class="header-anchor" href="#setuid-and-setgid-bits" aria-label="Permalink to &quot;SETUID AND SETGID BITS&quot;">​</a></h2><p><strong>chmod</strong> clears the set-group-ID bit of a regular file if the file&#39;s group ID does not match the user&#39;s effective group ID or one of the user&#39;s supplementary group IDs, unless the user has appropriate privileges. Additional restrictions may cause the set-user-ID and set-group-ID bits of <em>MODE</em> or <em>RFILE</em> to be ignored. This behavior depends on the policy and functionality of the underlying <strong>chmod</strong> system call. When in doubt, check the underlying system behavior.</p><p>For directories <strong>chmod</strong> preserves set-user-ID and set-group-ID bits unless you explicitly specify otherwise. You can set or clear the bits with symbolic modes like <strong>u+s</strong> and <strong>g-s</strong>. To clear these bits for directories with a numeric mode requires an additional leading zero like <strong>00755</strong>, leading minus like <strong>-6000</strong>, or leading equals like <strong>=755</strong>.</p><h2 id="restricted-deletion-flag-or-sticky-bit" tabindex="-1">RESTRICTED DELETION FLAG OR STICKY BIT <a class="header-anchor" href="#restricted-deletion-flag-or-sticky-bit" aria-label="Permalink to &quot;RESTRICTED DELETION FLAG OR STICKY BIT&quot;">​</a></h2><p>The restricted deletion flag or sticky bit is a single bit, whose interpretation depends on the file type. For directories, it prevents unprivileged users from removing or renaming a file in the directory unless they own the file or the directory; this is called the <em>restricted deletion flag</em> for the directory, and is commonly found on world-writable directories like <strong>/tmp</strong>. For regular files on some older systems, the bit saves the program&#39;s text image on the swap device so it will load more quickly when run; this is called the <em>sticky bit</em>.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>Change the mode of each FILE to MODE. With <strong>--reference</strong>, change the mode of each FILE to that of RFILE.</p><dl><dt><strong>-c</strong>, <strong>--changes</strong></dt><dd>like verbose but report only when a change is made</dd><dt><strong>-f</strong>, <strong>--silent</strong>, <strong>--quiet</strong></dt><dd>suppress most error messages</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>output a diagnostic for every file processed</dd><dt><strong>--no-preserve-root</strong></dt><dd>do not treat &#39;/&#39; specially (the default)</dd><dt><strong>--preserve-root</strong></dt><dd>fail to operate recursively on &#39;/&#39;</dd><dt><strong>--reference</strong>=<em>RFILE</em></dt><dd>use RFILE&#39;s mode instead of specifying MODE values. RFILE is always dereferenced if a symbolic link.</dd><dt><strong>-R</strong>, <strong>--recursive</strong></dt><dd>change files and directories recursively</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Each MODE is of the form &#39;[ugoa]*([-+=]([rwxXst]*|[ugo]))+|[-+=][0-7]+&#39;.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by David MacKenzie and Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>chmod</strong>(2)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/chmod%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/chmod\\</a>&gt; <br> or available locally via: info &#39;(coreutils) chmod invocation&#39;</p>',30);function l(e,g,c,m,u,p){return o(),r("div",null,[s("h1",d,n(e.$params.man),1),h])}const y=t(i,[["render",l]]);export{b as __pageData,y as default};
